local AnvilClampMaker = {}
local PRODUCTS = {
    iron_anvilclamp = { name = "Železni sponka za nakovalo", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni sponka za nakovalo za kovace." },
    bronze_anvilclamp = { name = "Bronast sponka za nakovalo", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast sponka za nakovalo za kovace." },
    silver_anvilclamp = { name = "Srebrn sponka za nakovalo", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn sponka za nakovalo za kovace." },
    gilded_anvilclamp = { name = "Pozlačen sponka za nakovalo", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen sponka za nakovalo za kovace." },
    jewel_set_anvilclamp = { name = "Draguljast sponka za nakovalo", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast sponka za nakovalo za kovace." },
    royal_sovereign_anvilclamp = { name = "Kraljevski suveren sponka za nakovalo", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren sponka za nakovalo z biseri za krono." },
}
local BUILDINGS = {
    anvilclamp_workshop = { name = "Anvilclamp delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    anvilclamp_house = { name = "Anvilclamp hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_anvilclamp_atelier = { name = "Mojstrski anvilclamp atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_anvilclamp_palace = { name = "Suverena anvilclamp palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
AnvilClampMaker.ironStock=18; AnvilClampMaker.bronzeStock=14; AnvilClampMaker.woodStock=10; AnvilClampMaker.leatherStock=8; AnvilClampMaker.silverStock=8; AnvilClampMaker.goldStock=6; AnvilClampMaker.jewelStock=4; AnvilClampMaker.pearlStock=4
AnvilClampMaker.productStock = {}; AnvilClampMaker.buildings = {}; AnvilClampMaker.maker = nil; AnvilClampMaker.activeMaking = {}; AnvilClampMaker.totalProducts = 0; AnvilClampMaker.dayTimer = 0
function AnvilClampMaker.init() AnvilClampMaker.ironStock=18; AnvilClampMaker.bronzeStock=14; AnvilClampMaker.woodStock=10; AnvilClampMaker.leatherStock=8; AnvilClampMaker.silverStock=8; AnvilClampMaker.goldStock=6; AnvilClampMaker.jewelStock=4; AnvilClampMaker.pearlStock=4; AnvilClampMaker.productStock={}; AnvilClampMaker.buildings={}; AnvilClampMaker.maker=nil; AnvilClampMaker.activeMaking={}; AnvilClampMaker.totalProducts=0; AnvilClampMaker.dayTimer=0; print("[AnvilClampMaker] Royal Anvil Clamp Maker System initialized (6 products, 4 buildings)") end
function AnvilClampMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; AnvilClampMaker.maker={name=n or ("Sponkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sponkar najet: %s (spretnost: %d)",AnvilClampMaker.maker.name,s),"success") end; return true end
function AnvilClampMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function AnvilClampMaker.build(id) local ok,e=AnvilClampMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(AnvilClampMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function AnvilClampMaker.getQualityBonus() local b=0; for _,bd in ipairs(AnvilClampMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function AnvilClampMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and AnvilClampMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and AnvilClampMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and AnvilClampMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and AnvilClampMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and AnvilClampMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and AnvilClampMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and AnvilClampMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and AnvilClampMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #AnvilClampMaker.buildings==0 then return false,"Potrebna sponkaška delavnica" end; if not AnvilClampMaker.maker then return false,"Potreben sponkar" end; return true end
function AnvilClampMaker.make(pt,qty) qty=qty or 1; local ok,e=AnvilClampMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then AnvilClampMaker.ironStock=AnvilClampMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then AnvilClampMaker.bronzeStock=AnvilClampMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then AnvilClampMaker.woodStock=AnvilClampMaker.woodStock-d.woodCost*qty end; if d.leatherCost then AnvilClampMaker.leatherStock=AnvilClampMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then AnvilClampMaker.silverStock=AnvilClampMaker.silverStock-d.silverCost*qty end; if d.goldCost then AnvilClampMaker.goldStock=AnvilClampMaker.goldStock-d.goldCost*qty end; if d.jewelCost then AnvilClampMaker.jewelStock=AnvilClampMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then AnvilClampMaker.pearlStock=AnvilClampMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if AnvilClampMaker.maker then t=math.max(1,t-math.floor(AnvilClampMaker.maker.skill/13)) end; table.insert(AnvilClampMaker.activeMaking,{id="anvilclamp_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function AnvilClampMaker.completeMaking(m) local q=1.0+(AnvilClampMaker.getQualityBonus()/100); if AnvilClampMaker.maker then q=q+(AnvilClampMaker.maker.skill/140) end; q=math.min(2.5,q); AnvilClampMaker.productStock[m.productType]=(AnvilClampMaker.productStock[m.productType] or 0)+m.quantity; AnvilClampMaker.totalProducts=AnvilClampMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if AnvilClampMaker.maker then AnvilClampMaker.maker.itemsMade=AnvilClampMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then AnvilClampMaker.maker.skill=math.min(100,AnvilClampMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sponka izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"anvilclamp.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function AnvilClampMaker.update(dt) if not _G.state then return end; AnvilClampMaker.dayTimer=AnvilClampMaker.dayTimer+dt; if AnvilClampMaker.dayTimer>=30 then AnvilClampMaker.dayTimer=0; for i=#AnvilClampMaker.activeMaking,1,-1 do local m=AnvilClampMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then AnvilClampMaker.completeMaking(m); table.remove(AnvilClampMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(AnvilClampMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if AnvilClampMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function AnvilClampMaker.getStats() return {ironStock=AnvilClampMaker.ironStock,bronzeStock=AnvilClampMaker.bronzeStock,woodStock=AnvilClampMaker.woodStock,leatherStock=AnvilClampMaker.leatherStock,silverStock=AnvilClampMaker.silverStock,goldStock=AnvilClampMaker.goldStock,jewelStock=AnvilClampMaker.jewelStock,pearlStock=AnvilClampMaker.pearlStock,productStock=AnvilClampMaker.productStock,numBuildings=#AnvilClampMaker.buildings,hasMaker=AnvilClampMaker.maker~=nil,makerName=AnvilClampMaker.maker and AnvilClampMaker.maker.name or "—",makerSkill=AnvilClampMaker.maker and AnvilClampMaker.maker.skill or 0,activeMaking=#AnvilClampMaker.activeMaking,totalProducts=AnvilClampMaker.totalProducts} end
return AnvilClampMaker
